      .look-card {
        padding: 1.2rem;
        min-height: 100%;
        display: grid;
        gap: 1rem;
      }

      .look-visual {
        min-height: 18rem;
        border-radius: var(--radius-lg);
        background:
          radial-gradient(circle at 28% 18%, rgba(255, 255, 255, 0.6), transparent 16%),
          radial-gradient(circle at 75% 18%, rgba(132, 221, 255, 0.34), transparent 23%),
          linear-gradient(135deg, #3a2a67 0%, #141928 42%, #0d1426 100%);
        position: relative;
        overflow: hidden;
      }

      .look-visual::before,
      .look-visual::after {
        content: "";
        position: absolute;
        border-radius: 999px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.82), rgba(255, 255, 255, 0.06));
      }

      .look-visual::before {
        width: 3.8rem;
        height: 12rem;
        left: 3.2rem;
        top: 2rem;
        transform: rotate(8deg);
      }

      .look-visual::after {
        width: 5rem;
        height: 9rem;
        right: 3.6rem;
        bottom: 2rem;
        opacity: 0.75;
      }

      .look-card p,
      .section-copy,
      .deal-card p,
      .story-card p,
      .product-card p,
      .newsletter p,
      .site-footer p {
        color: var(--color-muted-text);
      }

      .section {
        padding: 1rem 0;
      }

      .featured,
      .deals,
      .editorial,
      .newsletter,
      .site-footer {
        padding: 1.4rem;
      }

      .section-head {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.3rem;
      }

      .section-head p {
        margin: 0.5rem 0 0;
      }

      .filter-list {
        display: flex;
        flex-wrap: wrap;
        gap: 0.7rem;
      }

      .chip-button {
        min-height: 2.6rem;
        padding: 0.7rem 1rem;
        color: var(--color-muted-text);
      }

      .chip-button[aria-pressed="true"] {
        color: var(--color-text);
        background: rgba(157, 123, 255, 0.18);
        border-color: rgba(185, 152, 255, 0.62);
      }

      .product-grid,
      .deal-grid,
      .editorial-grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .product-card {
        display: grid;
        padding: 1rem;
        gap: 1rem;
      }

      .product-card[hidden] {
        display: none;
      }

      .product-visual,
      .deal-visual,
      .story-visual {
        min-height: 14rem;
        border-radius: var(--radius-lg);
      }

      .product-visual {
        background:
          radial-gradient(circle at 20% 18%, rgba(255, 255, 255, 0.58), transparent 16%),
          linear-gradient(135deg, #2b1c54, #0f1627 55%, #10192a);
        position: relative;
        overflow: hidden;
      }

      .product-visual::after {
        content: attr(data-badge);
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.4rem 0.7rem;
        border-radius: 999px;
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        background: rgba(12, 15, 24, 0.82);
        border: 1px solid rgba(255, 255, 255, 0.12);
      }

      .product-meta,
      .deal-meta,
      .story-meta {
        display: grid;
        gap: 0.45rem;
      }

      .product-link h3,
      .story-link h3 {
        font-size: 1.2rem;
      }

      .price-row {
        display: flex;
        align-items: baseline;
        justify-content: space-between;
