      }

      .product-card button,
      .deal-card a,
      .story-card a {
        min-height: 2.9rem;
      }

      .deal-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .deal-card,
      .story-card {
        overflow: hidden;
      }

      .deal-card {
        display: grid;
      }

      .deal-visual {
        background:
          linear-gradient(160deg, rgba(132, 221, 255, 0.22), rgba(157, 123, 255, 0.1)),
