        position: relative;
      }

      .deal-visual::after {
        content: "";
        position: absolute;
        inset: 1.4rem;
        border-radius: 1.2rem;
        border: 1px solid rgba(255, 255, 255, 0.14);
      }

      .deal-body,
      .story-body {
        display: grid;
        gap: 0.7rem;
        padding: 1.1rem;
      }

      .deal-tag,
      .story-tag {
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--color-accent-strong);
      }

      .deal-note {
        display: inline-flex;
        align-items: center;
        gap: 0.4rem;
        font-size: 0.92rem;
      }

      .editorial-grid {
        grid-template-columns: 1.2fr 0.8fr;
      }

      .story-card {
        display: grid;
        min-height: 100%;
      }

      .story-visual {
        background:
          radial-gradient(circle at 32% 24%, rgba(255, 255, 255, 0.5), transparent 18%),
          linear-gradient(135deg, #2c1f57 0%, #0d1525 58%, #08101b 100%);
        position: relative;
      }

      .story-visual::after {
        content: "";
        position: absolute;
        width: 9rem;
        height: 9rem;
        border-radius: 50%;
        right: 1.5rem;
        bottom: 1.5rem;
        background: radial-gradient(circle, rgba(132, 221, 255, 0.6), transparent 70%);
      }

      .story-stack {
        display: grid;
        gap: 1rem;
      }

      .newsletter-form {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        gap: 0.8rem;
        margin-top: 1rem;
      }

      .field {
        display: grid;
        gap: 0.5rem;
      }

      .field label {
        font-weight: 600;
      }

      .field input {
        min-height: 3rem;
        width: 100%;
        padding: 0.85rem 1rem;
        border-radius: 14px;
        border: 1px solid var(--color-border);
        color: var(--color-text);
        background: rgba(255, 255, 255, 0.03);
      }

      .field-help,
      .field-error,
      .status-text {
        font-size: 0.92rem;
      }

      .field-error {
        color: #ffb6c5;
        min-height: 1.25rem;
      }

      .status-text {
        min-height: 1.3rem;
        margin-top: 0.75rem;
        color: var(--color-success);
      }

      .site-footer {
        margin: 1rem 0 2rem;
      }

      .footer-grid {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        flex-wrap: wrap;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        white-space: nowrap;
        border: 0;
      }

      @media (prefers-reduced-motion: no-preference) {
        .hero-copy,
        .look-card,
        .product-card,
        .deal-card,
        .story-card {
          transition:
            transform 0.25s ease,
            border-color 0.25s ease,
            background-color 0.25s ease;
        }

        .look-card:hover,
        .product-card:hover,
        .deal-card:hover,
        .story-card:hover {
          transform: translateY(-4px);
          border-color: rgba(185, 152, 255, 0.5);
        }
      }

      @media (max-width: 980px) {
        .topbar,
        .section-head,
        .footer-grid {
          align-items: start;
        }

        .hero-panel,
        .editorial-grid,
        .product-grid,
        .deal-grid {
          grid-template-columns: 1fr;
        }

        .product-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 720px) {
        .topbar,
        .section-head,
        .footer-grid {
          flex-direction: column;
        }

        .topbar {
          border-radius: 28px;
        }

        .nav-list {
          gap: 0.75rem;
        }

        .stats-list,
        .product-grid,
        .deal-grid,
        .editorial-grid,
        .newsletter-form {
          grid-template-columns: 1fr;
        }

        .header-actions,
        .hero-actions,
        .filter-list,
        .product-card .actions {
          width: 100%;
        }

        .cart-pill,
        .ghost-button,
        .primary-button,
        .chip-button,
        .newsletter button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :focus-visible {
          outline-color: Highlight;
        }

        .topbar,
        .hero-copy,
        .hero-aside,
        .featured,
        .deals,
        .editorial,
        .newsletter,
        .site-footer,
        .look-card,
        .deal-card,
        .story-card,
        .product-card,
        .cart-pill,
        .ghost-button,
        .primary-button,
        .chip-button,
        .field input {
          border: 1px solid ButtonBorder;
        }

        .primary-button,
        .cart-pill,
        .ghost-button,
        .chip-button,
        .newsletter button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
