      }

      .footer-grid {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        flex-wrap: wrap;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        white-space: nowrap;
        border: 0;
      }

      @media (prefers-reduced-motion: no-preference) {
        .hero-copy,
        .look-card,
        .product-card,
        .deal-card,
        .story-card {
          transition:
            transform 0.25s ease,
            border-color 0.25s ease,
            background-color 0.25s ease;
        }

        .look-card:hover,
        .product-card:hover,
        .deal-card:hover,
        .story-card:hover {
          transform: translateY(-4px);
          border-color: rgba(185, 152, 255, 0.5);
        }
      }

      @media (max-width: 980px) {
