      body {
        margin: 0;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(157, 123, 255, 0.18), transparent 28%),
          radial-gradient(circle at 85% 12%, rgba(72, 179, 255, 0.14), transparent 24%),
          linear-gradient(180deg, #0c0f18 0%, #090a11 100%);
        color: var(--color-text);
        min-width: 320px;
        line-height: 1.5;
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      a:hover {
        color: var(--color-link);
      }

      img,
      svg {
        max-width: 100%;
      }

      button,
      input {
        font: inherit;
      }

      button {
        cursor: pointer;
      }

      :focus-visible {
        outline: 3px solid var(--color-focus);
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--color-text);
        color: #05060c;
        transform: translateY(-200%);
        transition: transform 0.2s ease;
        z-index: 1000;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .shell {
        width: min(calc(100% - 2rem), var(--max-width));
        margin: 0 auto;
      }

      .site-header {
        padding: 1rem 0 0;
      }

      .topbar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem 1.2rem;
        border: 1px solid rgba(255, 255, 255, 0.08);
        background: rgba(16, 19, 29, 0.8);
        backdrop-filter: blur(18px);
        border-radius: 999px;
        box-shadow: var(--shadow-soft);
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
      }

      .brand-mark {
        width: 2.5rem;
        height: 2.5rem;
        border-radius: 0.9rem;
        display: grid;
        place-items: center;
        background: linear-gradient(135deg, #c39eff, #76d6ff);
        color: #090a11;
        font-size: 1.1rem;
      }

      .nav-list,
      .stats-list,
      .filter-list,
      .product-grid,
      .deal-grid,
      .editorial-grid,
      .footer-links {
        list-style: none;
        padding: 0;
        margin: 0;
      }

      .nav-list,
      .footer-links {
        display: flex;
        gap: 1rem;
        flex-wrap: wrap;
      }

      .nav-list a,
      .footer-links a {
        color: var(--color-muted-text);
      }

      .header-actions {
        display: flex;
        align-items: center;
        gap: 0.75rem;
      }

      .cart-pill,
      .ghost-button,
      .primary-button,
      .chip-button {
        border-radius: 999px;
        border: 1px solid var(--color-border);
      }

      .cart-pill,
      .ghost-button,
      .primary-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.55rem;
        min-height: 2.9rem;
        padding: 0.75rem 1.1rem;
      }

      .cart-pill {
        color: var(--color-text);
        background: rgba(255, 255, 255, 0.03);
      }

      .primary-button {
        color: #090a11;
        background: linear-gradient(135deg, var(--color-accent-strong), #84ddff);
        border-color: transparent;
        font-weight: 700;
      }

      .ghost-button,
      .chip-button,
      .newsletter button {
        color: var(--color-text);
        background: rgba(255, 255, 255, 0.04);
      }

      .hero {
        padding: 1.6rem 0 1rem;
      }

      .hero-panel {
        display: grid;
        grid-template-columns: minmax(0, 1.2fr) minmax(320px, 0.8fr);
        gap: 1.5rem;
        align-items: stretch;
      }

      .hero-copy,
      .hero-aside,
      .featured,
      .deals,
      .editorial,
      .newsletter,
      .site-footer {
        background: linear-gradient(180deg, rgba(23, 27, 43, 0.95), rgba(12, 15, 24, 0.96));
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow-soft);
      }

      .hero-copy {
        position: relative;
        overflow: hidden;
        padding: clamp(2rem, 5vw, 4rem);
      }

      .hero-copy::after {
        content: "";
        position: absolute;
        inset: auto -10% -24% auto;
        width: 14rem;
        height: 14rem;
        border-radius: 50%;
        background: radial-gradient(circle, rgba(141, 222, 255, 0.44), transparent 68%);
        pointer-events: none;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.55rem;
        padding: 0.45rem 0.9rem;
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.06);
        color: var(--color-muted-text);
        font-size: 0.9rem;
      }

      h1,
      h2,
      h3 {
        line-height: 1.1;
        margin: 0;
      }

      h1 {
        margin-top: 1rem;
        font-size: clamp(2.8rem, 7vw, 5.4rem);
        max-width: 10ch;
      }

      .hero-copy p {
        max-width: 56ch;
        margin: 1rem 0 0;
        color: var(--color-muted-text);
        font-size: 1.05rem;
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.9rem;
        margin-top: 1.6rem;
      }

      .stats-list {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.9rem;
        margin-top: 2rem;
      }

      .stats-list li {
        padding: 1rem;
        border-radius: var(--radius-md);
        background: rgba(255, 255, 255, 0.04);
        border: 1px solid rgba(255, 255, 255, 0.06);
      }

      .stats-list strong {
        display: block;
        font-size: 1.45rem;
      }

      .stats-list span {
        color: var(--color-muted-text);
        font-size: 0.92rem;
      }

      .hero-aside {
        padding: 1.2rem;
        display: grid;
        gap: 1rem;
      }

      .look-card,
      .deal-card,
      .story-card,
      .product-card {
        border-radius: var(--radius-lg);
        background: rgba(255, 255, 255, 0.03);
        border: 1px solid rgba(255, 255, 255, 0.08);
      }

      .look-card {
        padding: 1.2rem;
        min-height: 100%;
        display: grid;
        gap: 1rem;
      }

      .look-visual {
        min-height: 18rem;
        border-radius: var(--radius-lg);
        background:
          radial-gradient(circle at 28% 18%, rgba(255, 255, 255, 0.6), transparent 16%),
          radial-gradient(circle at 75% 18%, rgba(132, 221, 255, 0.34), transparent 23%),
          linear-gradient(135deg, #3a2a67 0%, #141928 42%, #0d1426 100%);
        position: relative;
        overflow: hidden;
      }

      .look-visual::before,
      .look-visual::after {
        content: "";
        position: absolute;
        border-radius: 999px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.82), rgba(255, 255, 255, 0.06));
      }

      .look-visual::before {
        width: 3.8rem;
        height: 12rem;
        left: 3.2rem;
        top: 2rem;
        transform: rotate(8deg);
      }

      .look-visual::after {
        width: 5rem;
        height: 9rem;
        right: 3.6rem;
        bottom: 2rem;
        opacity: 0.75;
      }

      .look-card p,
      .section-copy,
      .deal-card p,
      .story-card p,
      .product-card p,
      .newsletter p,
      .site-footer p {
        color: var(--color-muted-text);
      }

      .section {
        padding: 1rem 0;
      }

      .featured,
      .deals,
      .editorial,
      .newsletter,
      .site-footer {
        padding: 1.4rem;
      }

      .section-head {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.3rem;
      }

      .section-head p {
        margin: 0.5rem 0 0;
      }

      .filter-list {
        display: flex;
        flex-wrap: wrap;
        gap: 0.7rem;
      }

      .chip-button {
        min-height: 2.6rem;
        padding: 0.7rem 1rem;
        color: var(--color-muted-text);
      }

      .chip-button[aria-pressed="true"] {
        color: var(--color-text);
        background: rgba(157, 123, 255, 0.18);
        border-color: rgba(185, 152, 255, 0.62);
      }

      .product-grid,
      .deal-grid,
      .editorial-grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .product-card {
        display: grid;
        padding: 1rem;
        gap: 1rem;
      }

      .product-card[hidden] {
        display: none;
      }

      .product-visual,
      .deal-visual,
      .story-visual {
        min-height: 14rem;
        border-radius: var(--radius-lg);
      }

      .product-visual {
        background:
          radial-gradient(circle at 20% 18%, rgba(255, 255, 255, 0.58), transparent 16%),
          linear-gradient(135deg, #2b1c54, #0f1627 55%, #10192a);
        position: relative;
        overflow: hidden;
      }

      .product-visual::after {
        content: attr(data-badge);
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.4rem 0.7rem;
        border-radius: 999px;
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        background: rgba(12, 15, 24, 0.82);
        border: 1px solid rgba(255, 255, 255, 0.12);
      }

      .product-meta,
      .deal-meta,
      .story-meta {
        display: grid;
        gap: 0.45rem;
      }

      .product-link h3,
      .story-link h3 {
        font-size: 1.2rem;
      }

      .price-row {
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 0.75rem;
      }

      .price-row strong,
      .deal-meta strong {
        font-size: 1.3rem;
      }

      .product-card .actions {
        display: flex;
        gap: 0.75rem;
        flex-wrap: wrap;
      }

      .product-card button,
      .deal-card a,
      .story-card a {
        min-height: 2.9rem;
      }

      .deal-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .deal-card,
      .story-card {
        overflow: hidden;
      }

      .deal-card {
        display: grid;
      }

      .deal-visual {
        background:
          linear-gradient(160deg, rgba(132, 221, 255, 0.22), rgba(157, 123, 255, 0.1)),
          linear-gradient(135deg, #15192a, #0d1019);
        position: relative;
      }

      .deal-visual::after {
        content: "";
        position: absolute;
        inset: 1.4rem;
        border-radius: 1.2rem;
        border: 1px solid rgba(255, 255, 255, 0.14);
      }

      .deal-body,
      .story-body {
        display: grid;
        gap: 0.7rem;
        padding: 1.1rem;
      }

      .deal-tag,
      .story-tag {
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--color-accent-strong);
      }

      .deal-note {
        display: inline-flex;
        align-items: center;
        gap: 0.4rem;
        font-size: 0.92rem;
      }

      .editorial-grid {
        grid-template-columns: 1.2fr 0.8fr;
      }

      .story-card {
        display: grid;
        min-height: 100%;
      }

      .story-visual {
        background:
          radial-gradient(circle at 32% 24%, rgba(255, 255, 255, 0.5), transparent 18%),
          linear-gradient(135deg, #2c1f57 0%, #0d1525 58%, #08101b 100%);
        position: relative;
      }

      .story-visual::after {
        content: "";
        position: absolute;
        width: 9rem;
        height: 9rem;
        border-radius: 50%;
        right: 1.5rem;
        bottom: 1.5rem;
        background: radial-gradient(circle, rgba(132, 221, 255, 0.6), transparent 70%);
      }

      .story-stack {
        display: grid;
        gap: 1rem;
      }

      .newsletter-form {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        gap: 0.8rem;
        margin-top: 1rem;
      }

      .field {
        display: grid;
        gap: 0.5rem;
      }

      .field label {
        font-weight: 600;
      }

      .field input {
        min-height: 3rem;
        width: 100%;
        padding: 0.85rem 1rem;
        border-radius: 14px;
        border: 1px solid var(--color-border);
        color: var(--color-text);
        background: rgba(255, 255, 255, 0.03);
      }

      .field-help,
      .field-error,
      .status-text {
        font-size: 0.92rem;
      }

      .field-error {
        color: #ffb6c5;
        min-height: 1.25rem;
      }

      .status-text {
        min-height: 1.3rem;
        margin-top: 0.75rem;
        color: var(--color-success);
      }

      .site-footer {
        margin: 1rem 0 2rem;
      }

      .footer-grid {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        flex-wrap: wrap;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        white-space: nowrap;
        border: 0;
      }

      @media (prefers-reduced-motion: no-preference) {
        .hero-copy,
        .look-card,
        .product-card,
        .deal-card,
        .story-card {
          transition:
            transform 0.25s ease,
            border-color 0.25s ease,
            background-color 0.25s ease;
        }

        .look-card:hover,
        .product-card:hover,
        .deal-card:hover,
        .story-card:hover {
          transform: translateY(-4px);
          border-color: rgba(185, 152, 255, 0.5);
        }
      }

      @media (max-width: 980px) {
        .topbar,
        .section-head,
        .footer-grid {
          align-items: start;
        }

        .hero-panel,
        .editorial-grid,
        .product-grid,
        .deal-grid {
          grid-template-columns: 1fr;
        }

        .product-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 720px) {
        .topbar,
        .section-head,
        .footer-grid {
          flex-direction: column;
        }

        .topbar {
          border-radius: 28px;
        }

        .nav-list {
          gap: 0.75rem;
        }

        .stats-list,
        .product-grid,
        .deal-grid,
        .editorial-grid,
        .newsletter-form {
          grid-template-columns: 1fr;
        }

        .header-actions,
        .hero-actions,
        .filter-list,
        .product-card .actions {
          width: 100%;
        }

        .cart-pill,
        .ghost-button,
        .primary-button,
        .chip-button,
        .newsletter button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :focus-visible {
          outline-color: Highlight;
        }

        .topbar,
        .hero-copy,
        .hero-aside,
        .featured,
        .deals,
        .editorial,
        .newsletter,
        .site-footer,
        .look-card,
        .deal-card,
        .story-card,
        .product-card,
        .cart-pill,
        .ghost-button,
        .primary-button,
        .chip-button,
        .field input {
          border: 1px solid ButtonBorder;
        }

        .primary-button,
        .cart-pill,
        .ghost-button,
        .chip-button,
        .newsletter button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <header class="site-header">
      <div class="shell">
        <div class="topbar">
          <a class="brand" href="#maincontent" aria-label="Noctra Atelier home">
            <span class="brand-mark" aria-hidden="true">N</span>
            <span>Noctra Atelier</span>
          </a>
          <nav aria-label="Primary">
            <ul class="nav-list">
              <li><a href="#featured-products">Featured</a></li>
              <li><a href="#daily-deals">Deals</a></li>
              <li><a href="#editorial-stories">Editorial</a></li>
            </ul>
          </nav>
          <div class="header-actions">
            <a class="ghost-button" href="#newsletter-signup">Join the list</a>
            <div class="cart-pill" aria-live="polite" aria-atomic="true">
              Cart <span id="cart-count">0</span>
            </div>
          </div>
        </div>
      </div>
    </header>

    <main id="maincontent" tabindex="-1">
      <section class="hero">
        <div class="shell">
          <div class="hero-panel">
            <div class="hero-copy">
              <span class="eyebrow">Curated retail for after-hours living</span>
              <h1>Dark luxury made easy to shop.</h1>
              <p>
                Explore design-led essentials, exclusive drops, and editorial picks for a polished
                home and wardrobe. Every collection is styled to feel cinematic, tactile, and
                ready to live with now.
              </p>
              <div class="hero-actions">
                <a class="primary-button" href="#featured-products">Shop featured products</a>
                <a class="ghost-button" href="#editorial-stories">Read the journal</a>
              </div>
              <ul class="stats-list" aria-label="Brand highlights">
                <li>
                  <strong>48h</strong>
                  <span>Express dispatch on core staples</span>
                </li>
                <li>
                  <strong>120+</strong>
                  <span>Design-forward products across home and style</span>
                </li>
                <li>
                  <strong>4.9/5</strong>
                  <span>Average rating from members and early access clients</span>
                </li>
              </ul>
            </div>

            <aside class="hero-aside" aria-labelledby="seasonal-look-heading">
              <article class="look-card">
                <div class="look-visual" aria-hidden="true"></div>
                <div>
                  <p class="deal-tag">Seasonal spotlight</p>
                  <h2 id="seasonal-look-heading">The Noir Residence edit</h2>
                  <p>
                    Smoked glass, textured boucle, and brushed metal accents create a layered look
                    for intimate evenings at home.
                  </p>
                </div>
                <a class="primary-button" href="#daily-deals">Browse the room set</a>
              </article>
            </aside>
          </div>
        </div>
      </section>

      <section class="section">
        <div class="shell">
          <div class="featured" id="featured-products">
            <div class="section-head">
              <div>
                <p class="deal-tag">Featured products</p>
                <h2>Best-selling pieces with a nightfall palette</h2>
                <p class="section-copy">
                  Filter the assortment by collection and add favorites to your cart instantly.
                </p>
              </div>
              <div>
                <p class="sr-only" id="filter-label">Filter featured products by collection</p>
                <div class="filter-list" role="group" aria-labelledby="filter-label">
                  <button class="chip-button" type="button" aria-pressed="true" data-filter="all">
                    All collections
                  </button>
                  <button class="chip-button" type="button" aria-pressed="false" data-filter="home">
                    Home
                  </button>
                  <button class="chip-button" type="button" aria-pressed="false" data-filter="style">
                    Style
                  </button>
                  <button class="chip-button" type="button" aria-pressed="false" data-filter="tech">
                    Tech
                  </button>
                </div>
              </div>
            </div>

            <ul class="product-grid" id="product-grid">
              <li>
                <article class="product-card" data-category="home">
                  <div class="product-visual" aria-hidden="true" data-badge="New"></div>
                  <div class="product-meta">
                    <a class="product-link" href="#newsletter-signup">
                      <h3>Halo smoked-glass lamp</h3>
                    </a>
                    <p>Ambient lighting with a sculpted silhouette and dimmable bronze stem.</p>
                    <div class="price-row">
                      <strong>$168</strong>
                      <span>Home</span>
                    </div>
                  </div>
                  <div class="actions">
                    <button
                      class="primary-button add-to-cart"
                      type="button"
                      data-product="Halo smoked-glass lamp"
                    >
                      Add to cart
                    </button>
                    <button
                      class="ghost-button"
                      type="button"
                      aria-label="Save: Halo smoked-glass lamp"
                    >
                      Save
                    </button>
                  </div>
                </article>
              </li>
              <li>
                <article class="product-card" data-category="style">
                  <div class="product-visual" aria-hidden="true" data-badge="Exclusive"></div>
                  <div class="product-meta">
                    <a class="product-link" href="#newsletter-signup">
                      <h3>Velour city trench</h3>
                    </a>
                    <p>Fluid outerwear cut with a relaxed drape and matte midnight finish.</p>
                    <div class="price-row">
                      <strong>$242</strong>
                      <span>Style</span>
                    </div>
                  </div>
                  <div class="actions">
                    <button
                      class="primary-button add-to-cart"
                      type="button"
                      data-product="Velour city trench"
                    >
                      Add to cart
                    </button>
                    <button class="ghost-button" type="button" aria-label="Save: Velour city trench">
                      Save
                    </button>
                  </div>
                </article>
              </li>
              <li>
                <article class="product-card" data-category="tech">
                  <div class="product-visual" aria-hidden="true" data-badge="Editor's pick"></div>
                  <div class="product-meta">
                    <a class="product-link" href="#newsletter-signup">
                      <h3>Echo wireless speaker</h3>
                    </a>
                    <p>Rich room sound, touch controls, and a soft-touch graphite enclosure.</p>
                    <div class="price-row">
                      <strong>$129</strong>
                      <span>Tech</span>
                    </div>
                  </div>
                  <div class="actions">
                    <button
                      class="primary-button add-to-cart"
                      type="button"
                      data-product="Echo wireless speaker"
                    >
                      Add to cart
                    </button>
                    <button class="ghost-button" type="button" aria-label="Save: Echo wireless speaker">
                      Save
                    </button>
                  </div>
                </article>
              </li>
              <li>
                <article class="product-card" data-category="home">
                  <div class="product-visual" aria-hidden="true" data-badge="Bestseller"></div>
                  <div class="product-meta">
                    <a class="product-link" href="#newsletter-signup">
                      <h3>Obsidian lounge throw</h3>
                    </a>
                    <p>Weighty brushed texture woven for deep contrast and soft evening comfort.</p>
                    <div class="price-row">
                      <strong>$96</strong>
                      <span>Home</span>
                    </div>
                  </div>
                  <div class="actions">
                    <button
                      class="primary-button add-to-cart"
                      type="button"
                      data-product="Obsidian lounge throw"
                    >
