        const productName = button.dataset.product || "Item";
        button.setAttribute("aria-label", "Add to cart: " + productName);

        button.addEventListener("click", () => {
          cartItems += 1;
          cartCount.textContent = String(cartItems);
          cartStatus.textContent = productName + " added to cart. Cart now has " + cartItems + " item" + (cartItems === 1 ? "." : "s.");
        });
      });

      newsletterForm.addEventListener("submit", (event) => {
        event.preventDefault();

        const emailValue = emailInput.value.trim();
        const emailValid = emailInput.validity.valid && emailValue !== "";

        if (!emailValid) {
          emailInput.setAttribute("aria-invalid", "true");
          emailError.textContent = "Enter a valid email address to join the list.";
          newsletterStatus.textContent = "";
          emailInput.focus();
          return;
        }

        emailInput.removeAttribute("aria-invalid");
        emailError.textContent = "";
        newsletterStatus.textContent = "Thanks for joining. Your first members-only edit is on the way.";
        newsletterForm.reset();
      });

      emailInput.addEventListener("input", () => {
        if (emailInput.hasAttribute("aria-invalid") && emailInput.validity.valid) {
          emailInput.removeAttribute("aria-invalid");
          emailError.textContent = "";
        }
      });
